/** Wall-clock milliseconds per pipeline stage (1.6.0). Every instant of the run is attributed to exactly one stage, so the stages sum to about latency.totalMs (minus queueMs and time before the analyzer starts). plan: model turns and schema exploration; sql: running queries; repair: from a failed query or failed verification until the repaired query returns (model + SQL); checks: result checks after the final query; render: writing the answer parts. With parallel candidates the attribution follows the latest stage change, so treat it as approximate. */
export interface LatencyStages {
  plan: number;
  sql: number;
  repair: number;
  checks: number;
  render: number;
}

